import { consumeBudgets, RateLimitError } from "@/lib/rate-limit";
import "server-only";
import { createHash } from "node:crypto";
import { Prisma } from "@/generated/prisma/client";
import { z } from "zod";
import { adminDb } from "./db";
import { requireAdmin, checkActor, freshAuthentication } from "./auth";
import {
  AdminError,
  overrideInput,
  suspensionInput,
  controlInput,
  type MutationResult,
} from "./contracts";
import { appendAudit } from "./audit";
import { reservationSelect, evidenceSelect } from "./projections";
import { countAdminUsage } from "./usage";
import { adminUserSelect } from "./projections";
import { ensureUsagePeriods, lockUsageOwner } from "@/lib/usage-ledger";
import { resolveUsagePeriods, UsagePeriodError } from "@/lib/usage-periods";
// Internal entrypoint still authenticates; exported server actions never accept an actor.
async function mutate<T extends { requestId: string; reasonCode: string }>(
  schema: z.ZodType<T>,
  input: unknown,
  action: string,
  target: (v: T) => string | null,
  work: (
    tx: Prisma.TransactionClient,
    v: T,
    actorId: string,
  ) => Promise<{
    before: Prisma.InputJsonObject;
    after: Prisma.InputJsonObject;
  }>,
): Promise<MutationResult> {
  try {
    const actor = await requireAdmin(true);
    await consumeBudgets(
      actor.id,
      action === "SENDING_CONTROL"
        ? ["admin", "systemActor", "systemGlobal"]
        : ["admin"],
      adminDb(),
    );
    const parsed = schema.safeParse(input);
    if (!parsed.success) throw new AdminError("INVALID_INPUT");
    const v = parsed.data,
      targetId = target(v),
      hash = createHash("sha256")
        .update(JSON.stringify([actor.id, action, targetId, v]))
        .digest("hex");
    return await adminDb().$transaction(
      async (tx) => {
        // Request serialization precedes stable actor/target owner ordering.
        await tx.$queryRaw`SELECT pg_advisory_xact_lock(hashtextextended(${v.requestId},73461))::text`;
        const ids = [
          ...new Set([actor.id, ...(targetId ? [targetId] : [])]),
        ].sort();
        await tx.$queryRaw`SELECT id FROM "User" WHERE id IN (${Prisma.join(ids)}) ORDER BY id FOR UPDATE`;
        await checkActor(tx, actor.id);
        if (!freshAuthentication(actor.authenticatedAt))
          throw new AdminError("REAUTH_REQUIRED");
        const replay = await tx.$queryRaw<
          {
            requestHash: string;
            actorIdSnapshot: string;
            action: string;
            targetIdSnapshot: string | null;
          }[]
        >`SELECT "requestHash","actorIdSnapshot",action,"targetIdSnapshot" FROM "AdminAuditSafe" WHERE "requestId"=${v.requestId}`;
        if (replay.length) {
          const r = replay[0];
          if (
            r.requestHash !== hash ||
            r.actorIdSnapshot !== actor.id ||
            r.action !== action ||
            r.targetIdSnapshot !== targetId
          )
            throw new AdminError("CONFLICT");
          return { ok: true as const, requestId: v.requestId };
        }
        if (targetId) {
          const u = await tx.user.findUnique({
            where: { id: targetId },
            select: { id: true, deletionRequestedAt: true },
          });
          if (!u || u.deletionRequestedAt) throw new AdminError("DENIED");
        }
        const diff = await work(tx, v, actor.id);
        await appendAudit(tx, {
          actorId: actor.id,
          targetId,
          action,
          requestId: v.requestId,
          requestHash: hash,
          reason: v.reasonCode,
          ...diff,
        });
        return { ok: true as const, requestId: v.requestId };
      },
      { timeout: 15000, maxWait: 10000 },
    );
  } catch (error) {
    return {
      ok: false,
      code:
        error instanceof RateLimitError
          ? "RATE_LIMITED"
          : error instanceof AdminError
            ? error.code
            : "UNAVAILABLE",
      ...(error instanceof RateLimitError
        ? { retryAfter: error.retryAfter }
        : {}),
    };
  }
}
export function changeOverride(input: unknown) {
  return mutate(
    overrideInput,
    input,
    "PLAN_OVERRIDE",
    (v) => v.targetId,
    async (tx, v) => {
      const u = await tx.user.findUniqueOrThrow({
        where: { id: v.targetId },
        select: {
          plan: true,
          subscriptionStatus: true,
          planOverride: true,
          planOverrideStartsAt: true,
          planOverrideExpiresAt: true,
        },
      });
      if (v.plan === "FREE" && !v.confirmation)
        throw new AdminError("INVALID_INPUT");
      const now = new Date(),
        starts = v.plan ? new Date(v.startsAt ?? now.toISOString()) : null,
        expires = v.plan
          ? new Date(
              v.expiresAt ?? new Date(+starts! + 30 * 86400000).toISOString(),
            )
          : null;
      if (expires && (expires <= now || expires <= starts!))
        throw new AdminError("INVALID_INPUT");
      await tx.user.updateMany({
        where: { id: v.targetId },
        data: {
          planOverride: v.plan,
          planOverrideStartsAt: starts,
          planOverrideExpiresAt: expires,
          planOverrideReason: v.plan ? v.reasonCode : null,
        },
      });
      // Re-evaluate buckets without campaign content or provider mutations.
      const updated = await tx.user.findUniqueOrThrow({
        where: { id: v.targetId },
        select: adminUserSelect,
      });
      try {
        const specs = resolveUsagePeriods(updated, now);
        await ensureUsagePeriods(await lockUsageOwner(tx, v.targetId), specs);
      } catch (error) {
        // An unresolved provider boundary must not invent calendar credit.
        if (!(error instanceof UsagePeriodError)) throw error;
      }
      return {
        before: {
          planOverride: u.planOverride,
          startsAt: u.planOverrideStartsAt?.toISOString() ?? null,
          expiresAt: u.planOverrideExpiresAt?.toISOString() ?? null,
        },
        after: {
          planOverride: v.plan,
          startsAt: starts?.toISOString() ?? null,
          expiresAt: expires?.toISOString() ?? null,
        },
      };
    },
  );
}
async function cancelReady(tx: Prisma.TransactionClient, userId: string) {
  // Match the ledger lock order before touching Send/reservation rows.
  const periods = await tx.$queryRaw<
    {
      id: string;
      kind: "DAILY" | "MONTHLY";
      startsAt: Date;
      operationalEndsAt: Date;
    }[]
  >`SELECT id,kind,"startsAt","operationalEndsAt" FROM "UsagePeriod" WHERE "userId"=${userId} ORDER BY kind,"startsAt",key,id FOR UPDATE`;
  const ready = await tx.$queryRaw<
    { id: string }[]
  >`SELECT s.id FROM "AdminSendMetadata" s JOIN "Campaign" c ON c.id=s."campaignId" WHERE c."userId"=${userId} AND s.status='QUEUED' AND s."deliveryState"='READY' AND s."attemptedAt" IS NULL AND s."sentAt" IS NULL AND NOT s."hasProviderMessage" AND NOT EXISTS (SELECT 1 FROM "UsageReservation" r WHERE r."userId"=${userId} AND r."sendId"=s.id AND (r.status NOT IN ('RESERVED','RELEASED') OR r."chargedAt" IS NOT NULL))`;
  if (ready.length) {
    const ids = ready.map((s) => s.id);
    await tx.usageReservation.updateMany({
      where: {
        userId,
        sendId: { in: ids },
        status: "RESERVED",
        chargedAt: null,
      },
      data: { status: "RELEASED", releasedAt: new Date() },
    });
    await tx.send.updateMany({
      where: {
        id: { in: ids },
        campaign: { userId },
        status: "QUEUED",
        deliveryState: "READY",
        attemptedAt: null,
      },
      data: {
        status: "CANCELLED",
        deliveryState: "DONE",
        cancelledAt: new Date(),
        claimToken: null,
        leaseExpiresAt: null,
        error: null,
      },
    });
  }
  const [rs, es] = await Promise.all([
    tx.usageReservation.findMany({
      where: { userId },
      select: reservationSelect,
    }),
    tx.usageImportEvidence.findMany({
      where: { userId },
      select: evidenceSelect,
    }),
  ]);
  for (const p of periods)
    await tx.usagePeriod.updateMany({
      where: { id: p.id, userId },
      data: countAdminUsage(p, rs, es),
    });
  // Content-free campaign completion, including attempted/uncertain work.
  await tx.$executeRaw`UPDATE "Campaign" c SET status=CASE WHEN EXISTS(SELECT 1 FROM "AdminSendMetadata" s WHERE s."campaignId"=c.id AND s.status='QUEUED') THEN 'SENDING' WHEN EXISTS(SELECT 1 FROM "AdminSendMetadata" s WHERE s."campaignId"=c.id AND s.status='FAILED') THEN 'COMPLETED_WITH_ERRORS' WHEN EXISTS(SELECT 1 FROM "AdminSendMetadata" s WHERE s."campaignId"=c.id AND s.status='CANCELLED') THEN 'COMPLETED_WITH_CANCELLATIONS' ELSE 'COMPLETED' END WHERE c."userId"=${userId} AND EXISTS(SELECT 1 FROM "AdminSendMetadata" s WHERE s."campaignId"=c.id)`;
}
export function changeSuspension(input: unknown) {
  return mutate(
    suspensionInput,
    input,
    "SUSPENSION",
    (v) => v.targetId,
    async (tx, v, actorId) => {
      if (v.targetId === actorId && v.suspended) throw new AdminError("DENIED");
      const u = await tx.user.findUniqueOrThrow({
        where: { id: v.targetId },
        select: { isSuspended: true },
      });
      await tx.user.updateMany({
        where: { id: v.targetId },
        data: {
          isSuspended: v.suspended,
          suspendedAt: v.suspended ? new Date() : null,
          suspensionReason: v.suspended ? v.reasonCode : null,
        },
      });
      if (v.suspended) await cancelReady(tx, v.targetId);
      return {
        before: { isSuspended: u.isSuspended },
        after: { isSuspended: v.suspended },
      };
    },
  );
}
export function changeControl(input: unknown) {
  return mutate(
    controlInput,
    input,
    "SENDING_CONTROL",
    () => null,
    async (tx, v) => {
      const rows = await tx.$queryRaw<
        { sendingEnabled: boolean; updatedAt: Date }[]
      >`SELECT "sendingEnabled","updatedAt" FROM "SystemControl" WHERE key='global' FOR UPDATE`;
      const row = rows[0];
      if (!row) throw new AdminError("UNAVAILABLE");
      if (row.updatedAt.toISOString() !== v.expectedUpdatedAt)
        throw new AdminError("CONFLICT");
      await tx.systemControl.updateMany({
        where: { key: "global", updatedAt: row.updatedAt },
        data: {
          sendingEnabled: v.sendingEnabled,
          updatedAt: new Date(Math.max(Date.now(), +row.updatedAt + 1)),
        },
      });
      return {
        before: { sendingEnabled: row.sendingEnabled },
        after: { sendingEnabled: v.sendingEnabled },
      };
    },
  );
}
